const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mahajanga = ee.Geometry.Point([46.3167, -15.7167]).buffer(5000); // 5km buffer around city
  const startDate = '2020-01-01';
  const endDate = '2020-01-31';

  // 2. Data Acquisition - CHIRPS daily precipitation
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(mahajanga);

  const collectionSize = chirps.size().getInfo();
  console.log(`January 2020 rainfall images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum monthly precipitation
  const monthlyRainfall = chirps.sum();

  // Check pixel count
  const pixelCount = monthlyRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: mahajanga,
    scale: 1000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean rainfall in mm
  const rainfallMm = monthlyRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: mahajanga,
    scale: 1000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Total rainfall (mm): ${rainfallMm ? rainfallMm.toFixed(1) : 'null'}`);

  // 5. Validation & Final Answer
  if (rainfallMm === null || rainfallMm === undefined || isNaN(rainfallMm) || rainfallMm < 0) {
    console.log("<answer>C3</answer>");
  } else {
    const rainfallInches = rainfallMm / 25.4;
    console.log(`Total rainfall (inches): ${rainfallInches.toFixed(1)}`);

    if (rainfallInches > 12) {
      console.log("<answer>A</answer>");
    } else {
      console.log("<answer>B</answer>");
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
